public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) return 0;

    int numDeposits = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                numDeposits++;
                dfs(grid, i, j);
            }
        }
    }
    return numDeposits;
}

private static void dfs(char[][] grid, int i, int j) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[i].length || grid[i][j] != '@') {
        return;
    }
    grid[i][j] = '*'; // Mark the oil pocket as visited
    dfs(grid, i - 1, j); // Up
    dfs(grid, i + 1, j); // Down
    dfs(grid, i, j - 1); // Left
    dfs(grid, i, j + 1); // Right
    dfs(grid, i - 1, j - 1); // Up-Left
    dfs(grid, i - 1, j + 1); // Up-Right
    dfs(grid, i + 1, j - 1); // Down-Left
    dfs(grid, i + 1, j + 1); // Down-Right
}

