    StringBuilder result = new StringBuilder();
    boolean ascending = true;

    while (result.length() < s.length()) {
        if (ascending) {
            for (int i = 0; i < 26; i++) {
                if (count[i] > 0) {
                    result.append((char) (i + 'a'));
                    count[i]--;
                }
            }
        } else {
            for (int i = 25; i >= 0; i--) {
                if (count[i] > 0) {
