public static int squarePermutations(int[] A) {
    boolean[] used = new boolean[A.length];
    List<Integer> path = new ArrayList<>();
    int[] result = new int[1];
    backtrack(A, used, path, result);
    return result[0];
}

private static void backtrack(int[] A, boolean[] used, List<Integer> path, int[] result) {
    if (path.size() == A.length) {
        result[0]++;
        return;
    }
    for (int i = 0; i < A.length; i++) {
        if (used[i] || (i > 0 && A[i] == A[i - 1] && !used[i - 1])) continue;
        if (path.isEmpty() || isPerfectSquare(path.get(path.size() - 1) + A[i])) {
            used[i] = true;
            path.add(A[i]);
            backtrack(A, used, path, result);
            path.remove(path.size() - 1);
            used[i] = false;
        }
    }
}

private static boolean isPerfectSquare(int num) {
    int root = (int) Math.sqrt(num);
    return root * root == num;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int maxArea = 0;
    Stack<Integer> stack = new Stack<>();

    for (int i = 0; i <= n; i++) {
        while (!stack.isEmpty() && (i == n || heights[stack.peek()] >= heights[i])) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, height * width);
        }
        stack.push(i);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) return new int[0];
    int m = mat.length, n = mat[0].length;
    int[] result = new int[m * n];
    int r = 0, c = 0, d = 0;
    int[][] dirs = {{-1, 1}, {1, -1}};
    for (int i = 0; i < m * n; i++) {
        result[i] = mat[r][c];
        r += dirs[d][0];
        c += dirs[d][1];
        if (r >= m) { r = m - 1; c += 2; d = 1 - d; }
        if (c >= n) { c = n - 1; r += 2; d = 1 - d; }
        if (r < 0) { r = 0; d = 1 - d; }
        if (c < 0) { c = 0; d = 1 - d; }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int length = digits.length;

    // Find the rightmost digit that is smaller than the digit next to it
    int i = length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, return -1
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of (i-th digit) that is greater than digits[i]
    int j = length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the digits after (i-th digit)
    Arrays.sort(digits, i + 1, length);

    // Convert the array of digits back to an integer
    return Integer.parseInt(new String(digits));
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[][] pairs = {{'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}};
    if (n == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }
    dfs(result, new char[n], 0, n - 1, pairs);
    return result;
}

private static void dfs(List<String> result, char[] chars, int left, int right, char[][] pairs) {
    if (left > right) {
        result.add(new String(chars));
        return;
    }
    for (char[] pair : pairs) {
        chars[left] = pair[0];
        chars[right] = pair[1];
        if (chars.length > 1 && chars[0] == '0') {
            continue;
        }
        if (left == right && pair[0] != pair[1]) {
            continue;
        }
        dfs(result, chars, left + 1, right - 1, pairs);
    }
}

public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Calculate the area of the triangle formed by the points
    // Using the determinant (area = 0 if collinear)
    int area = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);

    return area != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return 0;
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    int i2 = 0, i3 = 0, i5 = 0;
    int nextMultipleOf2 = 2;
    int nextMultipleOf3 = 3;
    int nextMultipleOf5 = 5;

    for (int i = 1; i < n; i++) {
        int nextUglyNumber = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
        uglyNumbers[i] = nextUglyNumber;

        if (nextUglyNumber == nextMultipleOf2) {
            i2++;
            nextMultipleOf2 = uglyNumbers[i2] * 2;
        }

        if (nextUglyNumber == nextMultipleOf3) {
            i3++;
            nextMultipleOf3 = uglyNumbers[i3] * 3;
        }

        if (nextUglyNumber == nextMultipleOf5) {
            i5++;
            nextMultipleOf5 = uglyNumbers[i5] * 5;
        }
    }

    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxEnergy = 1;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
        } else {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
    }

    return Math.max(maxEnergy, currentEnergy);
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    result.sort(Comparator.comparingInt(Integer::toString));
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    java.util.HashMap<Integer, Integer> frequencyMap = new java.util.HashMap<>();
    for (int num : nums) {
        frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder(word);
        result.append(reversedWord.reverse().toString()).append(" ");
    }
    return result.toString().trim();
}
